// Keep the existing notification/preference owners read-only except for their
// original writes. Only this dedicated adapter permits the two peak fields.
class OhOwnerAdapter
{
 var$inner,$db_connect_id;
 function __construct($inner){$this->inner=$inner;$this->db_connect_id=$inner->db_connect_id;}
 function __call($method,$args){return call_user_func_array(array($this->inner,$method),$args);}
 function sql_query($sql,$transaction=false){if(strpos($sql,'UPDATE fixture_config SET config_value=')===0&&preg_match("/WHERE config_name='record_online_(users|date)' AND HEX\\(config_name\\)=HEX\\('record_online_\\1'\\)$/D",$sql)){return$this->inner->inner->sql_query($sql,$transaction);}return$this->inner->sql_query($sql,$transaction);}
}
class OhSource extends TpSource
{
 function sql_dedicated_connection(){$c=parent::sql_dedicated_connection();if($GLOBALS['tp_factory']==='normal'){$c->inner=new OhOwnerAdapter($c->inner);}return$c;}
}
eval('namespace OhUiSink; function color_group_colorize_name($id,$plain=false,$name=null){if(!is_string($name)){throw new \\RuntimeException("Header must bind the current stored name");}return \\phpbb_stored_text($name);}');
function oh_prepare($locale='english',$peak=5,$date=1000)
{
 on_prepare($locale);tn_sql("INSERT INTO fixture_config(config_name,config_value) VALUES('record_online_users','$peak'),('record_online_date','$date')");$GLOBALS['board_config']['record_online_users']=$peak;$GLOBALS['board_config']['record_online_date']=$date;$GLOBALS['plus_config']['index_layout']='index_body.tpl';
}
function oh_context($topic=0,$forum=0){return phpbb_online_header_context($GLOBALS['db'],$GLOBALS['userdata'],$topic,$forum);}
function oh_record(){return phpbb_online_record_values(new OhPeerRows($GLOBALS['tn_peer']));}
class OhPeerRows{var$db;function __construct($db){$this->db=$db;}function rows($sql){$r=$this->db->sql_query($sql);nt_check($r!==false,'Own record observation');try{return$this->db->sql_fetchrowset($r);}finally{$this->db->sql_freeresult($r);}}}
function oh_expected($before,$count,$date){foreach($before['config']as$i=>$row){if($row['config_name']==='record_online_users'){$before['config'][$i]['config_value']=(string)$count;}elseif($row['config_name']==='record_online_date'){$before['config'][$i]['config_value']=(string)$date;}}return$before;}
function oh_header($code,$topic=0,$forum=0)
