 $topic_id=$topic;$forum_id=$forum;$previous=$phpbb_root_path;$phpbb_root_path=$oh_root.'/';
 try{eval('namespace OhUiSink;'.$code);return array('visible'=>$logged_visible_online,'hidden'=>$logged_hidden_online,'guests'=>$guests_online,'total'=>$total_online_users,'names'=>$online_userlist,'text'=>$l_online_users,'total_label'=>$l_t_user_s,'ready'=>$online_ready,'scope'=>$online_ready?$header_online['scope']:false,'peak'=>$board_config['record_online_users'],'date'=>$board_config['record_online_date']);}
 finally{$phpbb_root_path=$previous;}
}
